# Resume la validacion del periodo de retorno via duracion-magnitud (salida de periodo_retorno_via_magnitud.R)
# Se corre desde la raiz del repo. Entrada: DIR_PRES/via_magnitud_validacion.csv
DIR_PRES <- Sys.getenv("DIR_PRES", "data/output/presentacion")
suppressMessages(library(dplyr))
r <- readr::read_csv(file.path(DIR_PRES, "via_magnitud_validacion.csv"), show_col_types = FALSE)
dev <- function(K, E) { E <- pmax(E, 1e-9); sum(2 * ifelse(K > 0, K * log(K / E), 0) - 2 * (K - E)) }
r <- r %>% mutate(E_dm = n * p_dm, E_di = n * p_di, E_ind = n * p_ind_emp)
cat("pares con copula duracion-magnitud:", n_distinct(paste(r$slug, r$station_id)), " | puntos:", nrow(r), " | con ambas copulas:", n_distinct(paste(r$slug, r$station_id)[r$ambas]), "\n")
cat("\n== (A) Todos los pares: desviacion de Poisson (menor = mejor), via magnitud vs independencia con marginales empiricas\n")
print(r %>% group_by(corr, grupo = ifelse(grepl("^ola", slug), "Olas", "Periodos")) %>% summarise(pares = n_distinct(paste(slug, station_id)), puntos = n(), dev_dm = round(dev(obs, E_dm)), dev_ind = round(dev(obs, E_ind)), .groups = "drop") %>% as.data.frame())
cat("\n== (A2) Calibracion: observados / esperados por tramo de eventos esperados\n")
print(r %>% mutate(tramo = cut(E_dm, c(0, 1, 3, 10, 30, Inf), right = FALSE)) %>% group_by(corr, tramo) %>% summarise(puntos = n(), obs = sum(obs), esp_dm = round(sum(E_dm), 1), obs_sobre_esp = round(sum(obs) / sum(E_dm), 2), esp_ind = round(sum(E_ind), 1), obs_sobre_ind = round(sum(obs) / sum(E_ind), 2), .groups = "drop") %>% as.data.frame())
cat("\n== (B) Pares con ambas copulas (intensidad-duracion y duracion-magnitud)\n")
b <- r %>% filter(ambas, !is.na(p_di))
print(b %>% group_by(corr, grupo = ifelse(grepl("^ola", slug), "Olas", "Periodos")) %>% summarise(pares = n_distinct(paste(slug, station_id)), puntos = n(), dev_dm = round(dev(obs, E_dm)), dev_di = round(dev(obs, E_di)), dev_ind = round(dev(obs, E_ind)), .groups = "drop") %>% as.data.frame())
bb <- b %>% filter(E_dm >= 3 & E_di >= 3, corr == "d + 0,5")
cat("\nCociente T_dm / T_di (= p_di / p_dm), d + 0,5, en puntos con >= 3 eventos esperados:", nrow(bb), "puntos\n"); print(summary(round(bb$p_di / bb$p_dm, 2)))
cat("correlacion log(p_dm), log(p_di):", round(cor(log(bb$p_dm), log(bb$p_di)), 3), "\n")
cat("\n== (C) Ejemplo 87585 (si existe)\n"); print(as.data.frame(r %>% filter(station_id == "87585") %>% select(slug, corr, d, i, obs, E_dm, E_di, E_ind) %>% mutate(across(c(E_dm, E_di, E_ind), ~round(.x, 2))) %>% filter(corr == "d + 0,5") %>% head(30)))
